import { useState, useEffect, useRef } from "react";
var SOLEIL_AZTEC="data:image/png;base64,";

const FOND_IMG     = "https://raw.githubusercontent.com/vincallegari-ops/Azteca-1/main/src/assets/ui/FOND_IMG.webp";
const BARON_FONT = "https://raw.githubusercontent.com/vincallegari-ops/Azteca-1/main/src/assets/fonts/baron-neue.regular.otf";
const PATHWAY_FONT = "https://raw.githubusercontent.com/vincallegari-ops/Azteca-1/main/src/assets/fonts/PathwayGothicOne-Regular.ttf";

import Splash from "./component/screen/splash.jsx";
import Menu from "./component/screen/menu.jsx";
import Tutorial from "./component/screen/tutorial.jsx";
import ClanSelect from "./component/screen/clanselect.jsx";
import Reveal from "./component/screen/reveal.jsx";
import Founding  from "./component/screen/founding.jsx";
import EndScreen from "./component/screen/endscreen.jsx";
import AtkPopup  from "./component/popup/AtkPopup.jsx";
import DistribPopup   from "./component/popup/DistribPopup.jsx";
import TransfertPopup from "./component/popup/TransfertPopup.jsx";
import CollectPopup   from "./component/popup/CollectePopup.jsx";
import GameBoard, { resetTileTypeMap } from "./component/game/GameBoard.jsx";
import { GameUITop, GameUIBottom } from "./component/game/GameUI.jsx";
import CoinIcon    from "./component/shared/CoinIcon.jsx";
import DiceDisplay from "./component/shared/DiceDisplay.jsx";

import { MAX_TURNS, COLORS, ADV, BN, d6, d2x6, defB, capArmy, effAmount, hexNbV } from "./constants/Game.js";
import { genMap } from "./constants/Maps.js";
import { useGameState } from "./hooks/useGameState.js";
import { useCombat }    from "./hooks/useCombat.js";
import { useCollect }   from "./hooks/useCollect.js";
import { useAI }        from "./hooks/useAI.js";

// ── Animations globales ───────────────────────────────────────────────────────
function FL() {
  return (
    <style>{`
      @keyframes fadeIn    { from{opacity:0}            to{opacity:1} }
      @keyframes popIn     { from{opacity:0;transform:scale(0.85)} to{opacity:1;transform:scale(1)} }
      @keyframes slideUp   { from{opacity:0;transform:translateY(16px)} to{opacity:1;transform:translateY(0)} }
      @keyframes diceRoll  { 0%{transform:rotate(0deg) scale(1)} 25%{transform:rotate(-12deg) scale(1.15)} 50%{transform:rotate(8deg) scale(1.1)} 75%{transform:rotate(-4deg) scale(1.05)} 100%{transform:rotate(0deg) scale(1)} }
      @keyframes slideIn   { from{opacity:0;transform:translateX(-20px)} to{opacity:1;transform:translateX(0)} }
      .anim-fade  { animation:fadeIn 0.3s ease }
      .anim-pop   { animation:popIn 0.35s cubic-bezier(0.34,1.56,0.64,1) }
      .anim-slide { animation:slideUp 0.3s ease }
      .anim-dice  { animation:diceRoll 0.5s ease }
    `}</style>
  );
}

// ── Popup générique ───────────────────────────────────────────────────────────
function PU(p) {
  var onCloseRef = useRef(p.onClose);
  onCloseRef.current = p.onClose;
  useEffect(function() {
    if (!p.show) return;
    var t = setTimeout(function() { onCloseRef.current(); }, 1000);
    return function() { clearTimeout(t); };
  }, [p.show]);
  if (!p.show) return null;
  return (
    <div className="anim-fade" style={{ position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,0.7)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:999 }}>
      <div className="anim-pop" style={{ background:"#1E293B",border:"2px solid #334155",borderRadius:16,padding:"24px 28px",maxWidth:520,width:"92%",maxHeight:"80vh",overflowY:"hidden" }}>
        {p.title && <div style={{ fontFamily:"'BaronNeue','Black Ops One',serif",fontWeight:700,fontSize:18,color:"#FCD34D",marginBottom:12,textAlign:"center" }}>{p.title}</div>}
        <div style={{ color:"#CBD5E1",fontSize:14,lineHeight:1.7,marginBottom:8,textAlign:"center" }}>{p.children}</div>
      </div>
    </div>
  );
}
var CS = { height:"100%", background:"linear-gradient(170deg,#080C18 0%,#0F172A 40%,#151D2E 100%)", color:"#E2E8F0", fontFamily:"'Crimson Text',Georgia,serif" };

// ── Composant principal ───────────────────────────────────────────────────────
export default function Game() {

  // ── State global ─────────────────────────────────────────────────────────
  var s = useGameState();
  var {
    ph, sPh, pN, sPN, pC, sPC,
    mapData, setMapData, ti, mRows, mCols, sTi,
    ps, sPs, rv, sRv, playOrder, setPlayOrder, foundingOrder, setFoundingOrder,
    tn, sTn, gP, sGP, sl, sSl, af, sAf,
    aCt, sACt, aF, sAF, trMode, setTrMode,
    pop, sPop, aiQueue, setAiQueue, aiIdx, setAiIdx,
    turnAnn, setTurnAnn, atkErr, setAtkErr,
    phaseReady, setPhaseReady, passCd, setPassCd,
    quitConfirm, setQuitConfirm,
    pendingAtk, setPendingAtk, diceAnim, setDiceAnim, diceResult, setDiceResult,
    pendingET, setPendingET,
    pendingDistrib, setPendingDistrib, pendingTransfer, setPendingTransfer,
    humanTurnActive, setHumanTurnActive,
    floatNotifs, setFloatNotifs,
    collectChoice, setCollectChoice, collectQueue, setCollectQueue, collectIdx, setCollectIdx,
    displayPlayer, setDisplayPlayer, displayMsg, setDisplayMsg,
    aiDoneCbRef, timerRef, tiRef, psRef, tnRef, popRef,
    endTurnRef, endTurnCalledRef, notifIdRef,
    collectingRef, collectGenRef, pendingBonusRef,
    atkErrRef, phaseReadyRef, passCdRef,
  } = s;

  var pl = ps.length > 0 ? ps[0] : null;
  var pT = ps.length > 0 ? ti.filter(function(x) { return x.owner === 0; }) : [];
  var isAnimating = aiIdx >= 0;
  function hexNb(id) { return hexNbV(id, mRows, mCols); }

  // ── Hooks métier ──────────────────────────────────────────────────────────
  var { canLevy, canTax, autoCollect } = useCollect({
    ti, ps, tn, mRows, mCols, sTi, sPs,
    setFloatNotifs, setCollectIdx, collectingRef, collectGenRef, notifIdRef, COLORS,
  });

  var { doOneAi, playAiSteps } = useAI({
    mRows, mCols, setAiQueue, setAiIdx, aiDoneCbRef, BN,
  });

  // startLevy déclaré avant useCombat car useCombat en a besoin
  function startLevy(curTn, curTi, delay) {
    if (curTn === MAX_TURNS) { sGP("done"); setPendingET(true); return; }
    var run = function() {
      var myTiles = (curTi || tiRef.current).filter(function(x) { return x.owner === 0; });
      var eligible = myTiles.filter(function(t2) { return canLevy(t2, curTn) || canTax(t2, curTn); });
      if (eligible.length === 0) { sGP("build"); sSl(null); return; }
      sGP("levy");
      var q = eligible.map(function(t2) { return t2.id; });
      setCollectQueue(q); setCollectIdx(0);
    };
    if (delay) { setTimeout(run, delay); } else { run(); }
  }

  var { confirmAtk, applyAtk, nO } = useCombat({
    ti, ps, tn, aCt, sACt, aF, sAF, sTi, sPop, sGP, sSl, sAf, setTrMode,
    setPendingAtk, setDiceAnim, setDiceResult, diceResult, setPendingDistrib,
    startLevy, endTurn: function() { endTurnRef.current && endTurnRef.current(); },
    MAX_TURNS,
  });

  // ── Score ─────────────────────────────────────────────────────────────────
  function sc() {
    if (!ps.length) return [];
    return ps.map(function(p, i) {
      var il = ti.filter(function(x) { return x.owner === i; });
      return Object.assign({}, p, { idx: i, cnt: il.length, score: il.reduce(function(s2, x) { return s2 + x.size; }, 0) });
    }).sort(function(a, b) { return b.score - a.score; });
  }

  // ── useEffects ────────────────────────────────────────────────────────────
  useEffect(function() {
    if (isAnimating && aiIdx >= 0 && aiIdx < aiQueue.length) {
      var action = aiQueue[aiIdx];
      var p = ps.find(function(x) { return x.color === action.color; });
      if (p) { setDisplayPlayer(p); setDisplayMsg(action.text); }
    } else if (humanTurnActive && !isAnimating) {
      setDisplayPlayer(pl);
      setDisplayMsg("À vous de jouer");
    }
  }, [aiIdx, isAnimating, humanTurnActive]);

  useEffect(function() {
    if (aiIdx < 0) return;
    var q = aiQueue;
    if (aiIdx >= q.length) return;
    if (q[aiIdx].tiles) sTi(q[aiIdx].tiles);
    if (q[aiIdx].players) sPs(q[aiIdx].players);
    if (q[aiIdx].floats && q[aiIdx].floats.length > 0) {
      var stepColor = q[aiIdx].color || "#FCD34D";
      var floatList = q[aiIdx].floats;
      floatList.forEach(function(f, fi) {
        setTimeout(function() {
          notifIdRef.current++;
          var nf = Object.assign({}, f, { id: notifIdRef.current, static: true, color: stepColor });
          setFloatNotifs([nf]);
          setTimeout(function() { setFloatNotifs([]); }, 1000);
        }, fi * 1100);
      });
    }
    var stepDelay = q[aiIdx].delay !== undefined ? q[aiIdx].delay : 2000;
    timerRef.current = setTimeout(function() {
      if (aiIdx + 1 < q.length) { setAiIdx(aiIdx + 1); }
      else {
        setAiIdx(-1);
        setTimeout(function() {
          var cb = aiDoneCbRef.current; aiDoneCbRef.current = null;
          if (cb) cb();
        }, 1000);
      }
    }, stepDelay);
    return function() { if (timerRef.current) clearTimeout(timerRef.current); };
  }, [aiIdx, aiQueue]);

  useEffect(function() {
    if (ph !== "game" || gP !== "attack" || pop || isAnimating) return;
    if (!humanTurnActive) return;
    if (pendingDistrib || pendingTransfer) return;
    var mx = tn === 1 ? 1 : 2;
    if (aF || aCt >= mx) {
      if (tn === MAX_TURNS) { sGP("done"); setPendingET(true); }
      else { startLevy(tn, ti); }
      return;
    }
    var myTiles = ti.filter(function(x) { return x.owner === 0; });
    var canAct = myTiles.some(function(t) { return !t.isDesert && t.army >= 2; });
    if (!canAct) {
      if (tn === MAX_TURNS) { sGP("done"); setPendingET(true); }
      else { startLevy(tn, ti); }
    }
  }, [gP, humanTurnActive, aCt, aF, pendingDistrib, pendingTransfer]);

  useEffect(function() {
    if (ph !== "game" || gP !== "levy") return;
    if (pendingDistrib) return;
    if (collectIdx < 0 || collectIdx >= collectQueue.length) return;
    if (collectChoice) return;
    if (collectingRef.current) return;
    var curTi = tiRef.current;
    var tid = collectQueue[collectIdx];
    var t = curTi[tid];
    if (!t || t.owner !== 0 || t.isDesert) { setCollectIdx(function(i) { return i + 1; }); return; }
    var cL = canLevy(t, tn), cT = canTax(t, tn);
    if (!cL && !cT) { setCollectIdx(function(i) { return i + 1; }); return; }
    if (cL && cT) {
      var amtC = effAmount(curTi, tid, 0, mRows, mCols);
      setCollectChoice({ tileId: tid, amount: amtC });
      return;
    }
    collectingRef.current = true;
    autoCollect(tid, cL ? "army" : "tax");
  }, [collectIdx, collectQueue, collectChoice, gP, ph, tn, pendingDistrib]);

  useEffect(function() {
    if (ph !== "game" || gP !== "levy") return;
    if (collectIdx >= 0 && collectQueue.length > 0 && collectIdx >= collectQueue.length && !collectChoice) {
      setCollectQueue([]); setCollectIdx(-1); setFloatNotifs([]);
      setTimeout(function() { sGP("build"); sSl(null); }, 350);
    }
  }, [collectIdx, collectQueue, collectChoice, gP, ph]);

  useEffect(function() {
    if (ph !== "game" || gP !== "build") return;
    if (pop || isAnimating || pendingDistrib || pendingTransfer) return;
    if (!humanTurnActive) return;
    var curGold = ps.length > 0 ? ps[0].gold : 99;
    if (curGold < 5) {
      var t = setTimeout(function() {
        if (gP !== "build" || !humanTurnActive) return;
        sGP("done");
        setTimeout(function() { endTurnRef.current && endTurnRef.current(); }, 50);
      }, 500);
      return function() { clearTimeout(t); };
    }
  }, [gP, humanTurnActive, pendingDistrib, pendingTransfer, pop, isAnimating, ps]);

  useEffect(function() {
    if (!pendingET || ph !== "game" || gP !== "done" || isAnimating) return;
    setPendingET(false);
    endTurn();
  }, [pendingET, ph, gP, isAnimating]);

  useEffect(function() {
    if (ph !== "game") return;
    setPhaseReady(false); setPassCd(1);
    if (phaseReadyRef.current) clearTimeout(phaseReadyRef.current);
    if (passCdRef.current) clearInterval(passCdRef.current);
    passCdRef.current = setInterval(function() {
      setPassCd(function(prev) { if (prev <= 1) { clearInterval(passCdRef.current); return 0; } return prev - 1; });
    }, 1000);
    phaseReadyRef.current = setTimeout(function() { setPhaseReady(true); }, 1000);
    return function() {
      if (phaseReadyRef.current) clearTimeout(phaseReadyRef.current);
      if (passCdRef.current) clearInterval(passCdRef.current);
    };
  }, [gP]);

  // ── Fondation ─────────────────────────────────────────────────────────────
  function initR() {
    if (!pN.trim()) return;
    var av = [].concat(ADV).sort(function() { return Math.random() - 0.5; }).slice(0, 3);
    var pc = COLORS[pC], oc = COLORS.filter(function(_, i) { return i !== pC; });
    var all = [{ name: pN.trim(), face: "\uD83E\uDEC5", color: pc.h, emoji: "\uD83C\uDFF4", isHuman: true, strat: "player" }]
      .concat(av.map(function(a, i) { return { name: a.n, emoji: a.e, face: a.f, color: oc[i].h, isHuman: false, strat: a.strat || "balanced", desc: a.desc || "" }; }));
    sRv([].concat(all).sort(function() { return Math.random() - 0.5; }));
    sPh("reveal");
  }

  function startG() {
    resetTileTypeMap();
    var humanRvIdx = rv.findIndex(function(p) { return p.isHuman; });
    var aiInOrder = rv.filter(function(p) { return !p.isHuman; });
    var rePs = [Object.assign({}, rv[humanRvIdx], { id: 0, gold: 12 })];
    aiInOrder.forEach(function(a, i) { rePs.push(Object.assign({}, a, { id: i + 1, gold: 12 })); });
    var po = []; rv.forEach(function(p) { if (p.isHuman) po.push(0); else { var idx = rePs.findIndex(function(r) { return !r.isHuman && r.name === p.name; }); po.push(idx); } });
    var poFounding = po.slice().reverse();
    rePs[po[0]] = Object.assign({}, rePs[po[0]], { gold: rePs[po[0]].gold + 2 });
    rePs[po[1]] = Object.assign({}, rePs[po[1]], { gold: rePs[po[1]].gold + 1 });
    sPs(rePs); setPlayOrder(po); setFoundingOrder(poFounding);
    var nm = genMap(); setMapData(nm);
    sTn(0); sSl(null); sAf(null); sGP("attack"); sPop(null); setAiQueue([]); setAiIdx(-1);
    sPh("buy0");
  }

  function placeFounding(nii, npp, k) {
    var av = nii.filter(function(x) { return x.owner === null && !x.isDesert && x.size <= npp[k].gold; });
    if (av.length > 0) {
      av.sort(function(a, b) { return b.size - a.size; });
      var pk = av[0];
      nii[pk.id] = Object.assign({}, pk, { owner: k, army: pk.size, heldSince: 0, lastLevy: -99, lastTax: -99, isCapital: true, barracks: 1, bank: 1 });
      npp[k] = Object.assign({}, npp[k], { gold: npp[k].gold - pk.size });
    }
  }

  function buyF(idx) {
    var t = ti[idx]; if (t.owner !== null || t.isDesert || !pl || pl.gold < t.size) return;
    var fOrd = foundingOrder.length ? foundingOrder : playOrder;
    var humanPos = fOrd.indexOf(0);
    var ni = ti.map(function(i) { return Object.assign({}, i); });
    var np = ps.map(function(p) { return Object.assign({}, p); });
    ni[idx] = Object.assign({}, t, { owner: 0, army: t.size, heldSince: 0, lastLevy: -99, lastTax: -99, isCapital: true, barracks: 1, bank: 1 });
    np[0] = Object.assign({}, np[0], { gold: np[0].gold - t.size });
    var postSteps = [];
    var curNi = ni.map(function(x) { return Object.assign({}, x); });
    var curNp = np.map(function(x) { return Object.assign({}, x); });
    for (var oi = humanPos + 1; oi < fOrd.length; oi++) {
      var k = fOrd[oi]; if (k === 0) continue;
      placeFounding(curNi, curNp, k);
      var cap = curNi.find(function(t2) { return t2.owner === k && t2.isCapital; });
      postSteps.push({ text: curNp[k].name + " fonde " + (cap ? cap.name : "sa capitale"), color: curNp[k].color, delay: 800, tiles: curNi.map(function(x) { return Object.assign({}, x); }), players: curNp.map(function(x) { return Object.assign({}, x); }) });
    }
    var finalNi = postSteps.length > 0 ? postSteps[postSteps.length - 1].tiles : ni;
    var finalNp = postSteps.length > 0 ? postSteps[postSteps.length - 1].players : np;
    var humanPosNormal = playOrder.indexOf(0);
    var preAiL = []; for (var oi3 = 0; oi3 < humanPosNormal; oi3++) { var k3 = playOrder[oi3]; if (k3 !== 0) preAiL.push(k3); }
    function launchGame(ni2, np2) {
      sTi(ni2); sPs(np2); sTn(1); sPh("game"); sSl(null); sAf(null);
      setTurnAnn(1);
      setTimeout(function() {
        setTurnAnn(null);
        if (preAiL.length > 0) {
          playAiSteps(preAiL, ni2, np2, 1, function(ni3, np3) {
            if (!ni3.some(function(x) { return x.owner === 0; })) { sTi(ni3); sPs(np3); sPh("end"); return; }
            sTi(ni3); sPs(np3);
            sGP("attack"); sACt(0); sAF(false); sSl(null); sAf(null); sPop(null); setTrMode(false);
            setHumanTurnActive(true);
          }, COLORS);
        } else {
          sGP("attack"); sACt(0); sAF(false); sSl(null); sAf(null); sPop(null); setTrMode(false);
          setHumanTurnActive(true);
        }
      }, 800);
    }
    sTi(ni); sPs(np); sSl(null); sAf(null);
    if (postSteps.length > 0) {
      setAiQueue(postSteps); setAiIdx(0);
      aiDoneCbRef.current = function() { launchGame(finalNi, finalNp); };
    } else { launchGame(finalNi, finalNp); }
  }

  useEffect(function() {
    if (ph !== "buy0" || !ps.length) return;
    var fOrd = foundingOrder.length ? foundingOrder : playOrder;
    var humanPos = fOrd.indexOf(0);
    if (humanPos === 0) return;
    var ni = ti.map(function(i) { return Object.assign({}, i); });
    var np = ps.map(function(p) { return Object.assign({}, p); });
    var preSteps = [];
    for (var oi = 0; oi < humanPos; oi++) {
      var k = fOrd[oi]; if (k === 0) continue;
      placeFounding(ni, np, k);
      var cap = ni.find(function(t) { return t.owner === k && t.isCapital; });
      preSteps.push({ text: np[k].name + " fonde " + (cap ? cap.name : "sa capitale"), color: np[k].color, delay: 800, tiles: ni.map(function(x) { return Object.assign({}, x); }), players: np.map(function(x) { return Object.assign({}, x); }) });
    }
    if (preSteps.length > 0) { setAiQueue(preSteps); setAiIdx(0); aiDoneCbRef.current = null; }
    else { sTi(ni); sPs(np); }
  }, [ph]);

  // ── Erreur attaque ────────────────────────────────────────────────────────
  function showAtkErr(msg) {
    setAtkErr(msg);
    if (atkErrRef.current) clearTimeout(atkErrRef.current);
    atkErrRef.current = setTimeout(function() { setAtkErr(null); }, 1700);
  }

  // ── Clic sur la carte ─────────────────────────────────────────────────────
  function handleMapClick(ix) {
    if (ph !== "game" || isAnimating || turnAnn || pendingAtk || !humanTurnActive) return;
    var t = ti[ix];
    if (gP === "attack") {
      var maxAtk = tn === 1 ? 1 : 2;
      if (aCt >= maxAtk || aF) return;
      if (sl === null) {
        if (t.owner === 0 && !t.isDesert && t.army >= 2) { sSl(ix); sAf(null); setAtkErr(null); setTrMode(false); }
      } else {
        if (ix === sl) { sSl(null); sAf(null); setAtkErr(null); setTrMode(false); return; }
        if (t.isDesert) return;
        var fr = ti[sl];
        if (t.owner === 0) {
          if (!hexNb(sl).includes(ix)) {
            if (t.army >= 2) { sSl(ix); sAf(null); setAtkErr(null); setTrMode(false); }
            else { sSl(null); sAf(null); setTrMode(false); }
            return;
          }
          var maxT = Math.max(1, Math.floor(fr.army * 0.5));
          if (fr.army < 2) { showAtkErr("Min 2 soldats nécessaires pour transférer."); return; }
          setPendingTransfer({ fI: sl, tI: ix, max: maxT });
          return;
        }
        setTrMode(false);
        if (!hexNb(sl).includes(ix)) { showAtkErr("Terrain non adjacent."); return; }
        if (fr.army < t.army || fr.army < 2) { showAtkErr("Armée insuffisante (≥" + t.army + " requis)."); return; }
        if (tn <= 4 && t.owner !== null) { showAtkErr("Pas d'attaque entre joueurs avant le tour 5."); return; }
        setAtkErr(null);
        var _tg = ti[ix], _fr = ti[sl];
        var _defBonusV = _tg.owner === null ? Math.min(0, defB(_tg.army, _fr.army)) : defB(_tg.army, _fr.army);
        var _wallBonusV = _tg.wall ? 1 : 0;
        pendingBonusRef.current = { eDefBonus: _defBonusV, eWallBonus: _wallBonusV };
        setPendingAtk({ tI: ix, fI: sl });
      }
    } else if (gP === "levy") {
      return;
    } else if (gP === "build") {
      if (t.owner === 0 && !t.isDesert && !t.bType &&
          (!t.barracks && pl.gold >= 8 || !t.bank && pl.gold >= 8 || !t.wall && pl.gold >= 5)) sSl(ix);
    }
  }

  // ── Construction ─────────────────────────────────────────────────────────
  function doBld(idx, ty) {
    if (gP !== "build") return;
    var t = ti[idx]; if (t.owner !== 0 || t.isDesert) return;
    var co = ty === "wall" ? 5 : ty === "barracks" ? 8 : ty === "bank" ? 8 : 0;
    if (pl.gold < co || t.bType) return;
    var ni = ti.map(function(i) { return Object.assign({}, i); });
    var np = ps.map(function(p) { return Object.assign({}, p); });
    np[0] = Object.assign({}, np[0], { gold: np[0].gold - co });
    ni[idx] = Object.assign({}, t, { bType: ty, bTurns: ty === "wall" ? 1 : 2 });
    sTi(ni); sPs(np);
  }

  // ── Fin de tour ───────────────────────────────────────────────────────────
  function endTurn() {
    if (endTurnCalledRef.current) return;
    endTurnCalledRef.current = true;
    setTimeout(function() { endTurnCalledRef.current = false; }, 100);
    setHumanTurnActive(false);
    sSl(null); sAf(null); setTrMode(false);
    setFloatNotifs([]); setCollectChoice(null); setCollectQueue([]); setCollectIdx(-1);
    collectingRef.current = false; collectGenRef.current++;
    var humanTiles = ti.filter(function(x) { return x.owner === 0; });
    if (humanTiles.length === 0) { sPh("end"); return; }
    var humanPos = playOrder.indexOf(0);
    var postAi = []; for (var oi = humanPos + 1; oi < playOrder.length; oi++) { var k = playOrder[oi]; if (k !== 0) postAi.push(k); }
    var preAi  = []; for (var oi2 = 0; oi2 < humanPos; oi2++) { var k2 = playOrder[oi2]; if (k2 !== 0) preAi.push(k2); }
    var curTi = ti.map(function(x) { return Object.assign({}, x); });
    var curPs = ps.map(function(x) { return Object.assign({}, x); });

    function afterPostAi(ni, np) {
      if (!ni.some(function(x) { return x.owner === 0; })) { sTi(ni); sPs(np); sPh("end"); return; }
      ni.forEach(function(t, ix) {
        if (t.owner !== null && !t.isDesert) { ni[ix] = Object.assign({}, ni[ix], { army: capArmy(ni[ix].army + 1, ni[ix].size), leviedThis: false }); }
        if (t.owner !== null && t.owner !== 0 && t.bType && t.bTurns > 0) {
          ni[ix] = Object.assign({}, ni[ix], { bTurns: ni[ix].bTurns - 1 });
          if (ni[ix].bTurns <= 0) { var bt3 = ni[ix].bType; if (bt3 === "wall") ni[ix].wall = 1; else if (bt3 === "barracks") ni[ix].barracks = 1; else if (bt3 === "bank") ni[ix].bank = 1; ni[ix].bType = null; }
        }
      });
      if (tn % 2 === 0) {
        np = np.map(function(p, idx) {
          var banks = ni.filter(function(t) { return t.owner === idx && !t.isDesert && t.bank > 0; }).length;
          if (banks === 0) return p;
          return Object.assign({}, p, { gold: p.gold + banks * 3 });
        });
      }
      var nt = tn + 1;
      if (nt > MAX_TURNS) { sTi(ni); sPs(np); sPh("end"); return; }
      sTi(ni); sPs(np); sTn(nt);
      setTurnAnn(nt);
      setTimeout(function() {
        setTurnAnn(null);
        if (!ni.some(function(x) { return x.owner === 0; })) { sPh("end"); return; }
        function finalizeHumanBld(tiles) {
          var ft = tiles.map(function(x) { return Object.assign({}, x); });
          ft.forEach(function(t, ix) {
            if (t.owner === 0 && t.bType && t.bTurns > 0) {
              ft[ix] = Object.assign({}, ft[ix], { bTurns: ft[ix].bTurns - 1 });
              if (ft[ix].bTurns <= 0) { var btH = ft[ix].bType; if (btH === "wall") ft[ix].wall = 1; else if (btH === "barracks") ft[ix].barracks = 1; else if (btH === "bank") ft[ix].bank = 1; ft[ix].bType = null; }
            }
          });
          return ft;
        }
        if (preAi.length > 0) {
          playAiSteps(preAi, ni, np, nt, function(ni2, np2) {
            if (!ni2.some(function(x) { return x.owner === 0; })) { sTi(ni2); sPs(np2); sPh("end"); return; }
            var ni3 = finalizeHumanBld(ni2);
            sTi(ni3); sPs(np2);
            setHumanTurnActive(true);
            sGP("attack"); sACt(0); sAF(false); sSl(null); sAf(null); sPop(null); setTrMode(false);
          }, COLORS);
        } else {
          var niF = finalizeHumanBld(ni);
          sTi(niF);
          setHumanTurnActive(true);
          sGP("attack"); sACt(0); sAF(false); sSl(null); sAf(null); sPop(null); setTrMode(false);
        }
      }, 800);
    }

    if (postAi.length > 0) { playAiSteps(postAi, curTi, curPs, tn, afterPostAi, COLORS); }
    else { afterPostAi(curTi, curPs); }
  }
  endTurnRef.current = endTurn;

  // ── Highlights carte ──────────────────────────────────────────────────────
  var maxAtk = tn === 1 ? 1 : 2;
  var canAtk2 = gP === "attack" && aCt < maxAtk && !aF && !isAnimating;
  var nh = sl !== null ? hexNb(sl) : [];
  var si2 = sl !== null ? ti[sl] : null;
  var mapHlIds;
  if (gP === "attack" && !isAnimating && canAtk2) {
    if (!sl) { mapHlIds = []; }
    else {
      mapHlIds = nh.filter(function(nid) {
        var nt = ti[nid]; if (!nt || nt.isDesert) return false;
        if (nt.owner === 0) return si2 && si2.army >= 2;
        if (tn <= 4 && nt.owner !== null && nt.owner !== 0) return false;
        return si2 && si2.army >= 2 && si2.army >= nt.army;
      });
    }
  } else if (gP === "levy" && !isAnimating) {
    mapHlIds = [];
  } else if (gP === "build" && !isAnimating) {
    mapHlIds = pT.filter(function(t) {
      if (t.isDesert || t.bType) return false;
      if (!t.barracks && pl.gold >= 8) return true;
      if (!t.bank && pl.gold >= 8) return true;
      if (!t.wall && pl.gold >= 5) return true;
      return false;
    }).map(function(t) { return t.id; });
  } else { mapHlIds = []; }

  var curAiAction = isAnimating && aiIdx >= 0 && aiIdx < aiQueue.length ? aiQueue[aiIdx] : null;

  // ── Rendus des phases ─────────────────────────────────────────────────────
  if (ph === "splash")   return <Splash onDone={function() { sPh("menu"); }} />;
  if (ph === "menu")            return <Menu onNewGame={function() { sPh("name"); sPC(1); }} onTutorial={function() { sPh("tutorial"); }} />;
  if (ph === "tutorial")        return <Tutorial onBack={function() { sPh("menu"); }} fromGame={false}/>;
  if (ph === "tutorial_ingame") return <Tutorial onBack={function() { sPh("game"); }} fromGame={true}/>;  if (ph === "name")     return <ClanSelect onConfirm={function(name, colorIdx) { sPN(name); sPC(colorIdx); initR(); }} />;
  if (ph === "reveal")   return <Reveal rv={rv} onStart={startG} />;

  if (ph === "buy0") {
    return (
      <Founding pl={pl} isAnimating={isAnimating} sl={sl}>
        <GameBoard tiles={ti} players={ps} selected={isAnimating ? null : sl}
          onSelect={function(ix) {
            if (isAnimating) return;
            var t = ti[ix]; if (t.isDesert || t.owner !== null) return;
            if (pl && pl.gold >= t.size) { sSl(ix); buyF(ix); }
          }}
          rows={mRows} cols={mCols} />
      </Founding>
    );
  }

  if (ph === "end") {
    return <EndScreen sc={sc()} onReplay={function() { sPh("menu"); sPN(""); setMapData(genMap()); sPs([]); }} />;
  }

  if (!pl) return null;

  // ── Rendu ph==="game" ─────────────────────────────────────────────────────
  return (
    <div style={CS}>
      <FL />

      {/* Popup générique */}
      <PU show={pop !== null} title={pop ? pop.title : ""} onClose={function() {
        sPop(null);
        var mx = tn === 1 ? 1 : 2;
        if (gP === "attack" && (aF || aCt >= mx)) {
          if (tn === MAX_TURNS) { sGP("done"); endTurn(); }
          else { startLevy(tn, ti); }
        }
        sSl(null); sAf(null); setTrMode(false);
      }}>
        {pop && <div><DiceDisplay dice={pop.dice} /><div>{pop.msg}</div></div>}
      </PU>

      {/* Popup répartition */}
      {pendingDistrib && ti[pendingDistrib.fI] && ti[pendingDistrib.tI] && (
        <DistribPopup
          from={ti[pendingDistrib.fI]} to={ti[pendingDistrib.tI]}
          pl={pl} total={ti[pendingDistrib.fI].army}
          onConfirm={function(amt) {
            var pd = pendingDistrib;
            var ni2 = ti.map(function(i) { return Object.assign({}, i); });
            ni2[pd.fI] = Object.assign({}, ni2[pd.fI], { army: Math.max(1, ti[pd.fI].army - amt) });
            ni2[pd.tI] = Object.assign({}, ni2[pd.tI], { army: capArmy(ni2[pd.tI].army + amt, ni2[pd.tI].size) });
            sTi(ni2); setPendingDistrib(null); sSl(null); sAf(null); setTrMode(false);
            if (pd.newACt >= pd.mx2 || aF) {
              if (tn === MAX_TURNS) { sGP("done"); endTurn(); }
              else { startLevy(tn, ni2, 600); }
            }
          }}
          onCancel={function() {
            var pd = pendingDistrib;
            var ni2 = ti.map(function(i) { return Object.assign({}, i); });
            setPendingDistrib(null); sSl(null); sAf(null); setTrMode(false);
            if (pd.newACt >= pd.mx2 || aF) {
              if (tn === MAX_TURNS) { sGP("done"); endTurn(); }
              else { startLevy(tn, ni2, 600); }
            }
          }}
        />
      )}

      {/* Popup transfert */}
      {pendingTransfer && ti[pendingTransfer.fI] && ti[pendingTransfer.tI] && (
        <TrDistribPopup
          from={ti[pendingTransfer.fI]} to={ti[pendingTransfer.tI]}
          pl={pl} max={Math.max(1, Math.floor(ti[pendingTransfer.fI].army * 0.5))}
          onConfirm={function(amt) {
            var pt = pendingTransfer;
            var ni2 = ti.map(function(i) { return Object.assign({}, i); });
            ni2[pt.fI] = Object.assign({}, ni2[pt.fI], { army: ni2[pt.fI].army - amt });
            ni2[pt.tI] = Object.assign({}, ni2[pt.tI], { army: capArmy(ni2[pt.tI].army + amt, ni2[pt.tI].size) });
            sTi(ni2);
            var newACtTr = aCt + 1; var mxTr = tn === 1 ? 1 : 2;
            sACt(newACtTr); setPendingTransfer(null); sSl(null); sAf(null); setTrMode(false);
            if (newACtTr >= mxTr) {
              setTimeout(function() {
                if (tn === MAX_TURNS) { sGP("done"); endTurnRef.current && endTurnRef.current(); }
                else { startLevy(tn, ni2); }
              }, 800);
            }
          }}
          onCancel={function() { setPendingTransfer(null); sSl(null); sAf(null); setTrMode(false); }}
        />
      )}

      {/* Popup collecte */}
      {collectChoice && (
        <CollectPopup
          collectChoice={collectChoice} pl={pl}
          onArmy={function() { var cc = collectChoice; setCollectChoice(null); autoCollect(cc.tileId, "army"); }}
          onTax={function()  { var cc = collectChoice; setCollectChoice(null); autoCollect(cc.tileId, "tax");  }}
        />
      )}

      {/* Annonce de tour */}
      {turnAnn && (
        <div className="anim-fade" style={{ position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(255,255,255,0.95)",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",zIndex:998,overflow:"hidden" }}>
          <div style={{ fontFamily:"'BaronNeue','Black Ops One',serif",fontWeight:400,fontSize:"clamp(36px,10vw,64px)",color:"#111",letterSpacing:"0.14em",marginBottom:"clamp(12px,3vh,24px)",zIndex:2 }}>Tour {turnAnn}</div>
          <div style={{ width:"clamp(96px,27vw,156px)",height:"clamp(96px,27vw,156px)" }}>
            <img src={SOLEIL_AZTEC} style={{ width:"100%",height:"100%",objectFit:"contain" }} alt="" />
          </div>
        </div>
      )}

      {/* Confirmation quitter */}
      {quitConfirm && (
        <div className="anim-fade" style={{ position:"fixed",top:0,left:0,right:0,bottom:0,background:"rgba(0,0,0,0.82)",display:"flex",alignItems:"center",justifyContent:"center",zIndex:1000 }}>
          <div className="anim-pop" style={{ background:"#1E293B",border:"2px solid #334155",borderRadius:16,padding:"28px 32px",maxWidth:360,width:"92%",textAlign:"center" }}>
            <div style={{ fontSize:32,marginBottom:10 }}>🏳️</div>
            <div style={{ fontFamily:"'BaronNeue','Black Ops One',serif",fontWeight:900,fontSize:17,color:"#FCD34D",marginBottom:8 }}>Abandonner la partie ?</div>
            <div style={{ fontSize:13,color:"#94A3B8",marginBottom:20 }}>Vous revenez à l'écran d'accueil. La partie en cours sera perdue.</div>
            <div style={{ display:"flex",gap:10,justifyContent:"center" }}>
              <button onClick={function() { setQuitConfirm(false); sPh("menu"); sPN(""); setMapData(genMap()); sPs([]); setPendingAtk(null); setDiceAnim(false); setDiceResult(null); }} style={{ background:"linear-gradient(135deg,#DC2626,#991B1B)",color:"#FFF",border:"none",padding:"10px 22px",borderRadius:10,fontSize:14,fontFamily:"'BaronNeue','Black Ops One',serif",fontWeight:700,cursor:"pointer" }}>Quitter</button>
              <button onClick={function() { setQuitConfirm(false); }} style={{ background:"#0F172A",color:"#94A3B8",border:"1px solid #334155",padding:"10px 18px",borderRadius:10,fontSize:13,cursor:"pointer" }}>Annuler</button>
            </div>
          </div>
        </div>
      )}

      {/* Popup attaque */}
      {pendingAtk && (
        <AtkPopup
          tg={ti[pendingAtk.tI]} fr={ti[pendingAtk.fI]}
          pl={pl} ps={ps} diceAnim={diceAnim} diceResult={diceResult}
          nO={nO} defB={defB}
          onConfirm={function() { confirmAtk(pendingAtk); }}
          onApply={applyAtk}
          onCancel={function() { setPendingAtk(null); setDiceAnim(false); setDiceResult(null); }}
          pendingBonus={pendingBonusRef.current}
        />
      )}

      {/* Fond + UI de jeu */}
      <div style={{ position:"fixed",top:0,left:0,right:0,bottom:0,maxWidth:520,margin:"0 auto",overflow:"hidden",boxSizing:"border-box" }}>
        <img src={FOND_IMG} style={{ position:"fixed",inset:0,width:"100%",height:"100%",objectFit:"cover",zIndex:0,pointerEvents:"none" }} alt="" />
        <div style={{ position:"absolute",inset:0,background:"rgba(0,0,0,0.18)",zIndex:1,pointerEvents:"none" }} />
        <div style={{ position:"relative",zIndex:2 }}>
          <GameUITop
            tn={tn} ps={ps} ti={ti} pl={pl} playOrder={playOrder}
            gP={gP} isAnimating={isAnimating} curAiAction={curAiAction}
            scores={sc()}
            onTutorial={function() { sPh("tutorial"); }}
            onQuit={function() { setQuitConfirm(true); }}
          />
          <div style={{ padding:"4px 4px 0" }}>
            <GameBoard
              tiles={ti} players={ps} selected={sl} selected2={af}
              onSelect={handleMapClick} hlIds={mapHlIds}
              rows={mRows} cols={mCols} floatNotifs={floatNotifs} trMode={trMode}
            />
          </div>
          <GameUIBottom
            tn={tn} ps={ps} ti={ti} pl={pl}
            gP={gP} aCt={aCt} aF={aF} sl={sl}
            isAnimating={isAnimating} phaseReady={phaseReady}
            displayPlayer={displayPlayer} displayMsg={displayMsg}
            onPassAttack={function() { if (tn === MAX_TURNS) { sGP("done"); endTurn(); } else { startLevy(tn, ti); } sSl(null); sAf(null); setTrMode(false); }}
            onBuild={doBld}
            onEndTurn={function() { sGP("done"); endTurn(); }}
          />
        </div>
      </div>

    </div>
  );
}
